import { Component } from '@angular/core';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  host: {
    '[tabindex]': 'order()',
  },
})
export class PctAvatar {
  protected order(): number {
    return 0;
  }
}

export function reorder(avatar: PctAvatar): void {
  Object.assign(Object.getPrototypeOf(avatar), { order: () => 5 });
}
